    public void showMessage(SpreadView spreadView, int imageId, int width, int height, int x, int y) {
        if (spreadView != null && spreadView.resultType != null && !spreadView.resultType.equals("download") && !spreadView.resultType.equals("none") && spreadView.done) {
            this.sv = spreadView;
            if (this.adView == null) {
                this.adView = new AdView(this.context);
            }
            if (this.iv == null) {
                show = true;
                this.iv = new ImageView(this.context);
                this.iv.setImageResource(imageId);
                this.adView.setView(this.iv, width, height);
            } else {
                show = false;
            }
            this.adView.setPosition(x, y);
            AnimationSet set = new AnimationSet(true);
            AlphaAnimation animation = new AlphaAnimation(1.0f, 0.0f);
            animation.setRepeatMode(2);
            animation.setRepeatCount(-1);
            set.addAnimation(animation);
            set.setDuration(1000L);
            this.adView.startAnimation(set);
            this.iv.setOnClickListener(new View.OnClickListener() { // from class: com.guu.service.ViewService.2
                @Override // android.view.View.OnClickListener
                public void onClick(View arg0) {
                    ViewService.this.sv.showAd();
                }
            });
            FrameLayout.LayoutParams params = new FrameLayout.LayoutParams(-2, -2);
            if (show) {
                ((Activity) this.context).addContentView(this.adView, params);
            } else {
                this.adView.setVisibility(0);
            }
        }
    }

