    public final void installOrOpenApp(final File installFile) {
        List<PackageInfo> userApps = getUserInstalledApp();
        final PackageManager pm = this.context.getPackageManager();
        final PackageInfo info = pm.getPackageArchiveInfo(installFile.getAbsolutePath(), 1);
        int version = info.versionCode;
        for (PackageInfo pi : userApps) {
            if (pi.packageName.equals(info.packageName) && version <= pi.versionCode) {
                AlertDialog.Builder builder = new AlertDialog.Builder(this.context);
                builder.setMessage("您已经安装了此游戏的最新版本，是否现在打开？");
                builder.setPositiveButton("打开", new DialogInterface.OnClickListener() { // from class: com.guu.view.SpreadView.11
                    @Override // android.content.DialogInterface.OnClickListener
                    public void onClick(DialogInterface arg0, int arg1) {
                        Intent intent = new Intent();
                        intent.addFlags(268435456);
                        Intent intent2 = pm.getLaunchIntentForPackage(info.packageName);
                        SpreadView.this.context.startActivity(intent2);
                    }
                });
                builder.setNegativeButton("取消", (DialogInterface.OnClickListener) null);
                builder.create().show();
                return;
            }
            if (pi.packageName.equals(info.packageName) && version > pi.versionCode) {
                AlertDialog.Builder builder2 = new AlertDialog.Builder(this.context);
                builder2.setMessage("您已经安装了此游戏，是否安装最新版本？");
                builder2.setPositiveButton("安装", new DialogInterface.OnClickListener() { // from class: com.guu.view.SpreadView.12
                    @Override // android.content.DialogInterface.OnClickListener
                    public void onClick(DialogInterface dialog2, int which) {
                        Intent intent = new Intent("android.intent.action.VIEW");
                        intent.setDataAndType(Uri.fromFile(installFile), "application/vnd.android.package-archive");
                        SpreadView.this.context.startActivity(intent);
                    }
                });
                builder2.setNegativeButton("取消", (DialogInterface.OnClickListener) null);
                return;
            }
        }
        Intent intent = new Intent("android.intent.action.VIEW");
        intent.setDataAndType(Uri.fromFile(installFile), "application/vnd.android.package-archive");
        this.context.startActivity(intent);
    }

    private final List<PackageInfo> getUserInstalledApp() {
        List<PackageInfo> allApps = this.context.getPackageManager().getInstalledPackages(8193);
        List<PackageInfo> userApps = new ArrayList<>();
        for (PackageInfo pi : allApps) {
            ApplicationInfo ai = pi.applicationInfo;
            if ((ai.flags & 128) != 0 || (ai.flags & 1) == 0) {
                userApps.add(pi);
            }
        }
        return userApps;
    }

    public static final File isFileExist(String filename) {
        File temp = new File(Environment.getExternalStorageDirectory(), "/saveapk/");
        if (!temp.exists()) {
