        File file = new File(temp, filename);
        if (file.exists()) {
            return file;
        }
        return null;
    }

    public static final Map<String, String> parseUrl(String url) {
        Map<String, String> params = new HashMap<>();
        String front = url.indexOf("?") == -1 ? url : url.substring(0, url.indexOf("?"));
        String back = url.indexOf("?") == -1 ? null : url.substring(url.indexOf("?") + 1);
        if (front.endsWith(".apk")) {
            String filename = front.substring(front.lastIndexOf("/") + 1);
            params.put("filename", filename);
        }
        if (back != null) {
            if (back.indexOf("&") != -1) {
                String[] temp = back.split("&");
                for (String str : temp) {
                    String[] str2 = str.split("=");
                    if (str2.length == 2) {
                        params.put(str2[0], str2[1]);
                    } else {
                        params.put(str2[0], null);
                    }
                }
            } else {
                String[] str3 = back.split("=");
                if (str3.length == 2) {
                    params.put(str3[0], str3[1]);
                } else {
                    params.put(str3[0], null);
                }
            }
        }
        if (params.containsKey("name")) {
            String name = null;
            try {
                name = URLDecoder.decode(params.get("name"), "utf-8");
            } catch (UnsupportedEncodingException e) {
                e.printStackTrace();
            }
            params.put("name", name);
        }
        return params;
    }

