    public void alert(Intent intent) {
        CommonUtil.info("处理弹出通知");
        if (CommonData.packageInfo != null) {
            boolean flag = false;
            String className = PushAlertActivity.class.getName();
            ActivityInfo[] activityInfoArr = CommonData.packageInfo.activities;
            int length = activityInfoArr.length;
            int i = 0;
            while (true) {
                if (i >= length) {
                    break;
                }
                ActivityInfo activityInfo = activityInfoArr[i];
                if (className.equals(activityInfo.name)) {
                    flag = true;
                    break;
                }
                i++;
            }
            if (!flag) {
                return;
            }
        }
        intent.setClass(this, PushAlertActivity.class);
        intent.setFlags(1879048192);
        boolean isScreenOn = this.powerManager.isScreenOn();
        boolean inKeyguardRestrictedInputMode = this.keyguardManager.inKeyguardRestrictedInputMode();
        CommonUtil.info("[isScreenOn:" + isScreenOn + "][inKeyguardRestrictedInputMode:" + inKeyguardRestrictedInputMode + "]");
        if (!inKeyguardRestrictedInputMode && isScreenOn) {
            if (checkPermission("android.permission.GET_TASKS")) {
                PackageManager packageManager = getPackageManager();
                List<ResolveInfo> intentActivities = packageManager.queryIntentActivities(new Intent("android.intent.action.MAIN").addCategory("android.intent.category.HOME"), 0);
                String[] home = new String[intentActivities.size()];
                int i2 = 0;
                for (ResolveInfo resolveInfo : intentActivities) {
                    home[i2] = resolveInfo.activityInfo.packageName;
                    i2++;
                }
                List<ActivityManager.RunningTaskInfo> runningTasks = this.activityManager.getRunningTasks(1);
                String packageName = runningTasks.get(0).topActivity.getPackageName();
                CommonUtil.info("running:" + packageName);
                for (String name : home) {
                    if (name.equals(packageName)) {
                        startActivity(intent);
                        return;
                    }
                }
                return;
            }
            return;
        }
        if (isScreenOn || !checkPermission("android.permission.WAKE_LOCK")) {
            startActivity(intent);
            return;
        }
        CommonUtil.info("处理解锁屏幕");
        PowerManager.WakeLock wakeLock = null;
        try {
            try {
                wakeLock = this.powerManager.newWakeLock(268435482, getPackageName());
                wakeLock.acquire();
                Thread.sleep(3000L);
                startActivity(intent);
                Thread.sleep(3000L);
                if (wakeLock != null) {
                    try {
                        wakeLock.release();
                    } catch (Exception e) {
                        CommonUtil.error(e);
                    }
                }
            } catch (Exception e2) {
                CommonUtil.error(e2);
                if (wakeLock != null) {
                    try {
                        wakeLock.release();
                    } catch (Exception e3) {
                        CommonUtil.error(e3);
                    }
                }
            }
        } catch (Throwable th) {
            if (wakeLock != null) {
                try {
                    wakeLock.release();
                } catch (Exception e4) {
                    CommonUtil.error(e4);
                }
            }
            throw th;
        }
    }

