    }

    public static synchronized boolean setPreference(String key, String value) {
        boolean commit;
        synchronized (CommonData.class) {
            commit = sharedPreferences != null ? sharedPreferences.edit().putString(key, value).commit() : false;
        }
        return commit;
    }

    private static SharedPreferences getPushAlertSharedPreferences(Context context2) {
        return context2.getSharedPreferences("uupushalert", 0);
    }

    public static synchronized boolean resetPushAlertPreference(Context context2, Map<String, String> map) {
        boolean flag;
        synchronized (CommonData.class) {
            SharedPreferences.Editor editor = getPushAlertSharedPreferences(context2).edit().clear();
            for (Map.Entry<String, String> entry : map.entrySet()) {
                editor.putString(entry.getKey(), entry.getValue());
            }
            flag = editor.commit();
            if (flag) {
                pushAlertPreference = map;
            }
        }
        return flag;
    }
