    public void startDownloadMission(final DownloadMission mission) {
        if (isDownloading(mission)) {
            CommonUtil.info("mission is downloading: " + mission.toString());
            return;
        }
        DownloadMission oldMissionRecord = getMissionRecord(mission);
        if (oldMissionRecord == null) {
            int missionId = insertMissionRecord(mission);
            if (missionId < 0) {
                CommonUtil.error(new Exception("startDownloadMission fail"));
                return;
            }
            mission.setMissionId(missionId);
        } else {
            mission.setMissionId(oldMissionRecord.getMissionId());
        }
        downloadList.add(mission);
        currentMissionSize++;
        CommonUtil.info("current missionlist: " + currentMissionSize);
        if (notificationManager == null) {
            notificationManager = (NotificationManager) this.context.getSystemService("notification");
        }
        final int notificationId = mission.getMissionId();
        final Notification notification = newNotification(this.context);
