                mission.setCurrentLength(mission.getTotalLength());
                String filePath = mission.getLocalUri();
                File fileDir = new File(filePath);
                int index = filePath.indexOf(".bak");
                File downFile = new File(filePath.substring(0, index));
                fileDir.renameTo(downFile);
                Intent it = new Intent("android.intent.action.VIEW");
                it.setDataAndType(Uri.fromFile(downFile), "application/vnd.android.package-archive");
                PendingIntent pendingIntent = PendingIntent.getActivity(DownloadAssistant.this.context, 0, it, 0);
                notification.contentIntent = pendingIntent;
                notification.flags = 16;
                if (mission.getType() == 1) {
                    if (Spread.spreadView != null) {
                        Spread.spreadView.showInstallAlert("版本更新已下载完成，是否现在安装？", downFile.getAbsolutePath());
                    }
                    notification.setLatestEventInfo(DownloadAssistant.this.context, "版本更新下载完成,点击安装", mission.getName() == null ? "" : mission.getName(), pendingIntent);
                } else if (mission.getType() == 0) {
                    notification.setLatestEventInfo(DownloadAssistant.this.context, "下载完成,点击安装", mission.getName() == null ? "" : mission.getName(), pendingIntent);
                } else if (mission.getType() == 2) {
                    if (Spread.spreadView != null) {
                        Spread.spreadView.installPrompt(downFile);
                    }
                    notification.setLatestEventInfo(DownloadAssistant.this.context, "版本更新下载完成,点击安装", mission.getName() == null ? "" : mission.getName(), pendingIntent);
                } else if (mission.getType() == 3) {
                    if (Spread.spreadView != null) {
                        Spread.spreadView.showInstallAlert("版本更新已下载完成，是否现在安装？", downFile.getAbsolutePath());
                    }
                    notification.setLatestEventInfo(DownloadAssistant.this.context, "版本更新下载完成,点击安装", mission.getName() == null ? "" : mission.getName(), pendingIntent);
                }
                DownloadAssistant.notificationManager.notify(notificationId, notification);
                DownloadAssistant.this.updateMissionLengthRecord(mission);
                DownloadAssistant.downloadList.remove(mission);
                DownloadAssistant.currentMissionSize--;
                CommonUtil.info("finish mission: " + mission.toString());
            }

