    @Override // android.app.Service
    public IBinder onBind(Intent intent) {
        return null;
    }

    @Override // android.app.Service
    public void onDestroy() {
        super.onDestroy();
    }

    @Override // android.app.Service
    public void onCreate() {
        CommonUtil.info("new bds create " + getApplicationContext());
        CommonData.init(this);
        if (Environment.getExternalStorageState().equals("mounted")) {
            DownloadAssistant downloadAssistant = DownloadAssistant.getInstance();
            downloadAssistant.setContext(this);
            List<DownloadMission> brokenMission = downloadAssistant.getBrokenDownloadMissions();
            if (brokenMission != null) {
                for (DownloadMission mission : brokenMission) {
                    downloadAssistant.startDownloadMission(mission);
                }
            }
        }
        super.onCreate();
    }

    @Override // android.app.Service
    public void onStart(Intent intent, int startId) {
        Context appContext = getApplicationContext();
        CommonUtil.info("new bds start: " + startId + "      " + intent);
        CommonUtil.info("appContext: " + appContext);
        if (intent != null) {
            String intentAction = intent.getAction();
            CommonUtil.info(String.valueOf(getClass().getName()) + " onstart intent action: " + intentAction);
            if (ACTION_NEW_DOWNLOAD.equals(intentAction)) {
                if (Environment.getExternalStorageState().equals("mounted")) {
                    DownloadMission downMission = parserIntentToDownloadMission(intent);
                    if (downMission != null) {
                        DownloadAssistant downloadAssistant = DownloadAssistant.getInstance();
                        downloadAssistant.setContext(this);
                        downloadAssistant.startDownloadMission(downMission);
                        return;
                    }
                    Toast.makeText(this, "下载失败", 1).show();
                    return;
                }
                Toast.makeText(this, "sd卡不可用，请插入或打开sd卡再重试", 1).show();
            }
        }
    }

    private DownloadMission parserIntentToDownloadMission(Intent intent) {
        DownloadMission mission = null;
        if (intent != null) {
            String url = intent.getStringExtra("url");
            String name = intent.getStringExtra("name");
            String type = intent.getStringExtra("type");
            String savePath = intent.getStringExtra("savepath");
            CommonUtil.info("download intent: (url,name,type,savepath)(" + url + "," + name + "," + type + "," + savePath + ")");
            if (url == null || savePath == null) {
                CommonUtil.error(new Exception("url or savepath cant null"));
            } else {
                mission = new DownloadMission();
                mission.setUrl(url);
                mission.setLocalUri(savePath);
                mission.setName(name);
                if ("update".equals(type)) {
                    mission.setType(1);
                } else if ("download".equals(type)) {
                    mission.setType(2);
                } else if ("force".equals(type)) {
                    mission.setType(3);
                } else if ("common".equals(type)) {
                    mission.setType(0);
                }
            }
        }
        return mission;
    }
}

