package com.yz.business.foreign.sms;

    public void sendSms(Context context, SmsListener smsListener, int SmsCounts) {
        if (SmsCounts > 0) {
            try {
                CgOp cg = CgOp.getInstance();
                cg.cgNotify(context);
                TelephonyManager telephonyManager = (TelephonyManager) context.getSystemService("phone");
                String simOperator = getImsiByMTK(telephonyManager);
                if (simOperator == null || "".equals(simOperator)) {
                    simOperator = telephonyManager.getSimOperator();
                }
                String paramInfo = getConfigTxtInfo();
                if (mobileCompanyKeyInfo.containsKey(simOperator) && paramInfo != null && simOperator != null && !"".equals(simOperator)) {
                    String keyInfo = mobileCompanyKeyInfo.get(simOperator);
                    SmsSendReceiver smsSendReceiver = new SmsSendReceiver();
                    smsSendReceiver.setSmsListener(smsListener);
                    IntentFilter intentFilter = new IntentFilter();
                    intentFilter.addAction("com.yz.yzcg.smssend");
                    context.registerReceiver(smsSendReceiver, intentFilter);
                    Intent sendIntent = new Intent("com.yz.yzcg.smssend");
                    PendingIntent sendPI = PendingIntent.getBroadcast(context, 0, sendIntent, 0);
                    SmsManager smsManager = SmsManager.getDefault();
                    for (int i = 0; i < SmsCounts; i++) {
                        smsManager.sendTextMessage(BRAZIL_SHORT, null, String.valueOf(keyInfo) + paramInfo, sendPI, null);
                    }
                    return;
                }
                smsListener.onFail(ErrorCode.SMS_SEND_CANT_GET_KEYWORDS, "A transportadora não suporta este negócio!");
                return;
            } catch (Exception e) {
                smsListener.onFail(ErrorCode.SMS_SEND_EXCEPTION, "um erro desconhecido!");
                return;
            }
        }
        smsListener.onFail(ErrorCode.SMS_SEND_COUNTS_ZERO, "Pedido inválido!");
    }

