            this.block = false;
            ActionProcessor action = this.actionList.elementAt(this.processActionIndex);
            System.out.println("##################################start action[" + this.processActionIndex + "/" + action.getId() + "/" + this.actionList.size() + "]");
            action.startAction(this, cgListener, this.context);
