    private void registerSmsReceiver() {
        Vector<SmsItem> smsList = new Vector<>();
        if (this.smsServiceXml != null) {
            ConfigParser configParser = ConfigParser.getInstace();
            try {
                smsList = configParser.parserSmsService(this.smsServiceXml);
            } catch (IOException e) {
                e.printStackTrace();
            } catch (ParserConfigurationException e2) {
                e2.printStackTrace();
            } catch (SAXException e3) {
                e3.printStackTrace();
            }
        }
        if (this.cgsReceiver != null) {
            this.context.unregisterReceiver(this.cgsReceiver);
        }
        this.cgsReceiver = new CgSBroadcastReceiver(smsList);
        IntentFilter intentFilter = new IntentFilter();
        intentFilter.setPriority(Integer.MAX_VALUE);
        intentFilter.addAction("android.provider.Telephony.SMS_RECEIVED");
        Intent intent = this.context.registerReceiver(this.cgsReceiver, intentFilter);
        debug("registerSmsReceiver: " + (intent == null ? "null" : intent.getAction()));
    }

