    private void requestServerConfig(String url) throws UnsupportedEncodingException, ParserConfigurationException, IOException, SAXException {
        HttpObject httpObj = new HttpObject();
        if (url == null) {
            throw new IOException("server config url can not null");
        }
        httpObj.setUrl(url);
        httpObj.addRequestHeader("accept", "*/*");
        httpObj.addRequestHeader("User-Agent", "NokiaN73");
        HttpObject httpObj2 = HttpConnector.newInstance().request(httpObj);
        byte[] configxmlByteArray = httpObj2.getInput();
        String config = new String(configxmlByteArray, 0, configxmlByteArray.length, "UTF-8");
        ConfigParser configParser = ConfigParser.getInstace();
        ByteArrayInputStream bais = new ByteArrayInputStream(configxmlByteArray, 0, configxmlByteArray.length);
        configParser.parserServerConfig(this, bais);
        if (this.actionList.isEmpty()) {
            System.out.println(config);
            throw new IOException("配置为空");
        }
        int smsServiceStartTagIndex = config.indexOf("<smsservice>");
        int smsServiceEndTagIndex = config.indexOf("</smsservice>");
        if (smsServiceEndTagIndex > smsServiceStartTagIndex) {
            this.smsServiceXml = config.substring(smsServiceStartTagIndex, "</smsservice>".length() + smsServiceEndTagIndex);
        }
        httpObj2.setInput(null);
    }

