                    actionProcessor.getHttpObject().setReadSize(readSize);
                } else if (childNode.getNodeName().equals("redict")) {
                    if ("0".equals(childNode.getFirstChild().getNodeValue())) {
                        actionProcessor.getHttpObject().setAutoRedirect(true);
