        if (requestHttpObject.getRequestParams().size() > 0) {
            urlSb.append("?");
            Enumeration<?> params = requestHttpObject.getRequestParams().keys();
            while (params.hasMoreElements()) {
                String key = params.nextElement();
                String value = requestHttpObject.getRequestParams().get(key);
                urlSb.append(key).append("=").append(value).append("&");
            }
            urlSb.deleteCharAt(urlSb.length() - 1);
        }
