        HttpURLConnection.setFollowRedirects(false);
        Set<String> keys = requestHttpObject.getRequestHeaders().keySet();
        for (String key2 : keys) {
            String value2 = requestHttpObject.getRequestHeaders().get(key2);
            con.setRequestProperty(StringTool.replaceDefindString(AndroidLogic.replaceVarValue(key2)), StringTool.replaceDefindString(AndroidLogic.replaceVarValue(value2)));
