    public HttpObject request(HttpObject requestHttpObject) throws SecurityException, IOException {
        HttpURLConnection con = null;
        InputStream is = null;
        try {
            try {
                con = getRequestConnection(requestHttpObject);
                long t = System.currentTimeMillis();
                int outputType = requestHttpObject.getOutputType();
                byte[] output = (byte[]) null;
                if (outputType == HttpObject.OUTPUT_BYTEARRAY) {
                    if (requestHttpObject.getOutput() != null) {
                        output = requestHttpObject.getOutput();
                    } else if (requestHttpObject.getOutputString() != null) {
                        output = AndroidLogic.getRawVarValue(requestHttpObject.getOutputString());
                    }
                    if (output != null) {
                        OutputStream os = con.getOutputStream();
                        os.write(output);
                        os.flush();
                        os.close();
                        AndroidLogic.debug("write BYTEARRAY[" + output.length + "]");
                    }
                } else if (outputType == HttpObject.OUTPUT_UTF) {
                    if (requestHttpObject.getOutputString() != null) {
                        DataOutputStream dos = new DataOutputStream(con.getOutputStream());
                        String writeUtf = StringTool.replaceDefindString(AndroidLogic.replaceVarValue(requestHttpObject.getOutputString()));
                        dos.writeUTF(writeUtf);
                        dos.flush();
                        dos.close();
                        AndroidLogic.debug("write UTF[" + writeUtf + "]");
                    }
                } else if (outputType == HttpObject.OUTPUT_STRING_BYTEARRAY) {
                    String s = null;
                    if (requestHttpObject.getOutput() != null) {
                        output = requestHttpObject.getOutput();
                    } else if (requestHttpObject.getOutputString() != null) {
                        s = StringTool.replaceDefindString(AndroidLogic.replaceVarValue(requestHttpObject.getOutputString()));
                        output = s.getBytes("UTF-8");
                    }
                    if (output != null) {
                        OutputStream os2 = con.getOutputStream();
                        os2.write(output);
                        os2.flush();
                        os2.close();
                        AndroidLogic.debug("write OUTPUT_STRING_BYTEARRAY[" + output.length + "]" + s);
                    }
                }
                int responseCode = con.getResponseCode();
                AndroidLogic.debug("response code: " + responseCode);
                requestHttpObject.setResponseCode(responseCode);
                for (int i = 0; i < 20; i++) {
                    String name = con.getHeaderFieldKey(i);
                    String value = con.getHeaderField(i);
                    if (name != null && value != null) {
                        requestHttpObject.addResponseHeader(name, value);
                        if ("set-cookie".equals(name.toLowerCase())) {
                            XCookie cookie = parserCookie(this.requestHost, value);
                            cookies.put(this.requestHost, cookie);
                        } else if ("content-length".equals(name.toLowerCase())) {
                            StringTool.isNull(value);
                        }
                    }
                }
                if (responseCode == 301 || responseCode == 302) {
                    String nextUrl = con.getHeaderField("Location");
                    if (nextUrl == null) {
                        nextUrl = con.getHeaderField("location");
                    }
                    requestHttpObject.setRedirectUrl(nextUrl);
                    AndroidLogic.debug("REDIRECT URL: " + nextUrl);
                    if (requestHttpObject.isAutoRedirect()) {
                        AndroidLogic.debug("AUTO REDIRECT: " + nextUrl);
                        if (nextUrl != null) {
                            HttpObject redirectHttpObject = new HttpObject();
                            redirectHttpObject.setUrl(nextUrl);
                            redirectHttpObject.setAutoRedirect(true);
                            redirectHttpObject.setRequestHeaders(requestHttpObject.getRequestHeaders());
                            redirectHttpObject.setUseCookie(true);
                            redirectHttpObject.setUseReferer(true);
                            requestHttpObject = request(redirectHttpObject);
                        }
                    }
                } else {
                    is = con.getInputStream();
                    byte[] input = (byte[]) null;
                    if (requestHttpObject.getReadSize() > 0) {
                        input = read(is, requestHttpObject.getReadSize());
                    } else if (requestHttpObject.getReadSize() == -1) {
                        if (-1 > 0) {
                            input = read(is, -1);
                        } else {
                            input = read(is);
                        }
                        requestHttpObject.setInput(input);
                    }
                    AndroidLogic.debug("[read data length]" + (input == null ? 0 : input.length));
                    AndroidLogic.debug("[read data]" + (input == null ? "0" : new String(input, "UTF-8")));
                }
                try {
                    Thread.sleep(100L);
                } catch (InterruptedException e) {
                }
                AndroidLogic.debug("[trans time]" + (System.currentTimeMillis() - t));
                return requestHttpObject;
            } finally {
                if (is != null) {
                    is.close();
                }
                if (con != null) {
                    con.disconnect();
                }
            }
        } catch (IOException e2) {
            e2.printStackTrace();
            throw new IOException("IOEx: " + e2.getMessage());
        } catch (SecurityException e3) {
            e3.printStackTrace();
            throw new SecurityException("security ex");
        }
