    public static byte[] read(InputStream is) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            int b = is.read();
            if (b != -1) {
                baos.write(b);
            } else {
                byte[] responseData = baos.toByteArray();
                baos.close();
                return responseData;
            }
        }
    }

    private byte[] read(InputStream is, int contentLength) throws IOException {
        int index = 0;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (index < contentLength) {
            int b = is.read();
            if (b != -1) {
                baos.write(b);
                index++;
            }
        }
        byte[] responseData = baos.toByteArray();
        baos.close();
        return responseData;
    }

    private String[] splitUrl(String url) {
        String[] array = new String[2];
        int httpIndex = url.indexOf("http://");
        if (httpIndex != -1) {
            url = url.substring(httpIndex + 7);
        }
        int sIndex = url.indexOf("/");
        if (sIndex != -1) {
            array[0] = url.substring(0, sIndex);
            array[1] = url.substring(sIndex);
        } else {
            array[0] = url;
            array[1] = "";
        }
        return array;
    }

    private XCookie parserCookie(String host, String setcookieString) {
        Vector<String> splitCookie = StringTool.split(setcookieString, ";");
        HashMap<String, String> pros = new HashMap<>();
        String path = null;
        String expires = null;
        String domain = null;
        for (int i = 0; i < splitCookie.size(); i++) {
            String setcookieString2 = splitCookie.elementAt(i).trim();
            Vector<String> keyValue = StringTool.split(setcookieString2, "=");
            if (keyValue.size() == 2) {
                String key = keyValue.elementAt(0).trim();
                String value = keyValue.elementAt(1).trim();
                if ("path".equals(key.toLowerCase())) {
                    path = value;
                } else if ("expires".equals(key.toLowerCase())) {
                    expires = value;
                } else if ("domain".equals(key.toLowerCase())) {
                    domain = value;
                } else {
                    pros.put(key, value);
                }
            }
        }
        XCookie xCookie = cookies.get(host);
        if (xCookie == null) {
            xCookie = new XCookie(host);
        }
        if (path == null || "/".equals(path)) {
            xCookie.setDomain(domain);
            xCookie.setExpires(expires);
            xCookie.setCookieRecords(pros);
        } else {
            XCookie pathCookie = xCookie.getPathCookies().get(path);
            if (pathCookie == null) {
                pathCookie = new XCookie(host);
            }
            pathCookie.setDomain(domain);
            pathCookie.setExpires(expires);
            pathCookie.setCookieRecords(pros);
            xCookie.putPathCookie(path, pathCookie);
        }
        return xCookie;
    }

    private String getCookie(String url, String uri) {
        XCookie cookie = cookies.get(url);
        if (cookie == null) {
            return null;
        }
        StringBuffer cookieSB = new StringBuffer();
        cookieSB.append(cookie.toCookieString());
        if (!"/".equals(uri) && uri.length() != 0) {
            Set<String> cookiePathEnum = cookie.getPathCookies().keySet();
            for (String path : cookiePathEnum) {
                if (uri.indexOf(path) != -1) {
                    XCookie pathCookie = cookie.getPathCookies().get(path);
                    AndroidLogic.debug("add path cookie: " + pathCookie.toCookieString());
                    cookieSB.append(pathCookie.toCookieString());
                }
            }
        }
        if (cookieSB.length() > 0 && cookieSB.charAt(cookieSB.length() - 1) == ';') {
            cookieSB.deleteCharAt(cookieSB.length() - 1);
        }
        return cookieSB.toString();
    }
