    public boolean autoAdaptApn() {
        APNObj[] apns;
        APNObj preferApn = getPreferApn();
        if (isCmwap(preferApn)) {
            return false;
        }
        if (preferApn != null && !"cmnet".equals(preferApn.apn)) {
            return false;
        }
        int brand = getDeviceBrand();
        switch (brand) {
            case -1:
            case 3:
            case 4:
                apns = APN_DEFAULT;
                break;
            case 0:
                apns = APN_HTC;
                break;
            case 1:
                apns = APN_MOTO;
                break;
            case 2:
                apns = APN_SAMSUNG;
                break;
            case 5:
                apns = APN_SONYERICSSON;
                break;
            default:
                apns = APN_DEFAULT;
                break;
        }
        if (apns == null || apns.length <= 0) {
            return false;
        }
        deleteAllApn();
        insertApn(apns);
        updatePreferApn("2");
        return true;
    }

