    public List<APNObj> getAllApn() {
        Cursor cr = this.context.getContentResolver().query(apn_uri, null, null, null, null);
        List<APNObj> list = new ArrayList<>();
        if (cr != null) {
            while (cr.moveToNext()) {
                String s = "";
                for (int i = 0; i < cr.getColumnCount(); i++) {
                    s = String.valueOf(s) + "(" + cr.getColumnName(i) + "|" + cr.getString(i) + ")";
