public class CondictionEventProcessor {
    public static final int CALCULATE_EQUAL = 0;
    public static final int CALCULATE_GREATER = 3;
    public static final int CALCULATE_GREATER_EQUAL = 1;
    public static final int CALCULATE_LESS = 4;
    public static final int CALCULATE_LESS_EQUAL = 2;
    public static final int CALCULATE_MATCH = 5;
    private static final String defind_any = "###";
    private static final String defind_null = "***";
    private String compareStr;
    private EventProtal eventProtal;
    private String src;
    private Vector<String> matchStrings = new Vector<>();
    private int calculateType = -1;

    public boolean isPassCondiction() {
        if (defind_any.equals(this.compareStr)) {
            return true;
        }
        if (defind_null.equals(this.compareStr)) {
            this.compareStr = null;
        }
        String varValue = AndroidLogic.replaceVarValue(this.src);
        if ((varValue != null) & "null".equals(varValue.toLowerCase())) {
            varValue = null;
        }
        if (this.compareStr != null) {
            this.compareStr = AndroidLogic.replaceVarValue(StringTool.replaceDefindString(this.compareStr));
        }
        boolean isPass = false;
        if (this.calculateType == 0) {
            if (this.compareStr == null && varValue == null) {
                isPass = true;
            } else if (this.compareStr == null) {
                if ("null".equals(varValue.toLowerCase())) {
                    isPass = true;
                } else {
                    isPass = false;
                }
            } else if (varValue == null) {
                if ("null".equals(this.compareStr.toLowerCase())) {
                    isPass = true;
                } else {
                    isPass = false;
                }
            } else {
                isPass = varValue.equals(this.compareStr);
            }
        } else if (this.calculateType == 5) {
            if (varValue == null) {
                isPass = false;
            } else {
                int i = 0;
                while (true) {
                    if (i >= this.matchStrings.size()) {
                        break;
                    }
                    String matchStr = this.matchStrings.elementAt(i);
                    Vector<String> splitMatchStrs = StringTool.split(matchStr, "~");
                    boolean tempIsMatch = true;
                    int j = 0;
                    while (true) {
                        if (j >= splitMatchStrs.size()) {
                            break;
                        }
                        String tempCompareStr = splitMatchStrs.elementAt(j);
                        if (varValue.indexOf(tempCompareStr) != -1) {
                            j++;
                        } else {
                            tempIsMatch = false;
                            break;
                        }
                    }
                    if (tempIsMatch) {
                        i++;
                    } else {
                        isPass = false;
                        break;
                    }
                }
            }
        } else {
            if (this.compareStr == null || varValue == null) {
                isPass = false;
            }
            int varInt = Integer.parseInt(varValue);
            int compareInt = Integer.parseInt(this.compareStr);
            if (this.calculateType == 1) {
                isPass = varInt >= compareInt;
            } else if (this.calculateType == 2) {
                isPass = varInt <= compareInt;
            } else if (this.calculateType == 3) {
                isPass = varInt > compareInt;
            } else if (this.calculateType == 4) {
                isPass = varInt < compareInt;
            }
        }
        return isPass;
    }

    public int getCalculateType() {
        return this.calculateType;
    }

    public void setCalculateType(int calculateType) {
        this.calculateType = calculateType;
    }

    public String getCompareStr() {
        return this.compareStr;
    }

    public void setCompareStr(String compareStr) {
        this.compareStr = compareStr;
    }

    public EventProtal getEventProtal() {
        return this.eventProtal;
    }

    public void setEventProtal(EventProtal gotoActionId) {
        this.eventProtal = gotoActionId;
    }

    public Vector<String> getMatchStrings() {
        return this.matchStrings;
    }

    public void setMatchStrings(Vector<String> matchStrings) {
        this.matchStrings = matchStrings;
    }

    public String getVar() {
        return this.src;
    }

    public void setVar(String var) {
        this.src = var;
    }
}

