            if (this.resultValue != null) {
                if (!StringTool.isNull(this.attribute)) {
                    int attrIndex = this.resultValue.indexOf(this.attribute);
                    int startIndex2 = this.resultValue.indexOf("\"", attrIndex);
                    int endIndex2 = this.resultValue.indexOf("\"", startIndex2 + 1);
                    if (startIndex2 == -1 || endIndex2 == -1) {
                        startIndex2 = this.resultValue.indexOf("'", attrIndex);
                        endIndex2 = this.resultValue.indexOf("'", startIndex2 + 1);
                    }
                    if (endIndex2 > startIndex2) {
                        this.resultValue = this.resultValue.substring(startIndex2 + 1, endIndex2).trim();
