                if (this.resultValue != null) {
                    this.startPoint = AndroidLogic.replaceVarValue(this.startPoint);
                    this.endPoint = AndroidLogic.replaceVarValue(this.endPoint);
                    if (this.startPoint == null || this.startPoint.length() == 0) {
                        startIndex = 0;
                    } else {
                        startIndex = this.resultValue.indexOf(this.startPoint);
                    }
                    if (this.endPoint == null || this.endPoint.length() == 0) {
                        endIndex = this.resultValue.length();
                    } else {
                        endIndex = this.resultValue.indexOf(this.endPoint, startIndex);
                    }
                    if (endIndex <= startIndex || startIndex == -1 || endIndex == -1) {
                        this.resultValue = null;
                    } else {
                        this.resultValue = this.resultValue.substring((this.startPoint == null ? 0 : this.startPoint.length()) + startIndex, endIndex).trim();
