    public boolean changeCmwap(long sleepTime) {
        if (checkPermission("android.permission.ACCESS_NETWORK_STATE")) {
            ConnectivityManager connectivityManager = (ConnectivityManager) this.context.getSystemService("connectivity");
            NetworkInfo networkInfo = connectivityManager.getActiveNetworkInfo();
            if (networkInfo != null && networkInfo.isConnected() && "cmwap".equals(networkInfo.getExtraInfo())) {
                AndroidLogic.debug("当前已经是cmwap连接");
                return true;
            }
            if (checkPermission("android.permission.WRITE_APN_SETTINGS")) {
                AndroidLogic.debug("该系统支持自动切换连接方式");
                TelephonyManager telephonyManager = (TelephonyManager) this.context.getSystemService("phone");
                String simOperator = telephonyManager.getSimOperator();
                if ("46000".equals(simOperator) || "46002".equals(simOperator) || "46007".equals(simOperator)) {
                    Cursor cursor = null;
                    try {
                        try {
                            ContentResolver resolver = this.context.getContentResolver();
                            cursor = resolver.query(APN_URI, new String[]{"_id"}, "numeric = ? and apn='cmwap' and type like '%default%'", new String[]{simOperator}, null);
                            String id = null;
                            while (cursor.moveToNext() && (id = cursor.getString(0)) == null) {
                            }
                            cursor.close();
                            if (id == null) {
                                ContentValues values = new ContentValues();
                                values.put("name", "cmwap");
                                values.put("apn", "cmwap");
                                values.put("type", "default,supl");
                                values.put("numeric", simOperator);
                                values.put("mcc", "460");
                                values.put("mnc", simOperator.substring(3));
                                values.put("proxy", "10.0.0.172");
                                values.put("port", HttpConnector.CMWAP_GAME_PORT);
                                Uri newRow = resolver.insert(APN_URI, values);
                                id = newRow.getLastPathSegment();
                            }
                            if (this.apnId == null) {
                                cursor = resolver.query(PREFERAPN_URI, new String[]{"_id"}, null, null, null);
                                while (cursor.moveToNext()) {
                                    this.apnId = cursor.getString(0);
                                    if (this.apnId != null) {
                                        break;
                                    }
                                }
                                cursor.close();
                            }
                            ContentValues values2 = new ContentValues();
                            values2.put("apn_id", id);
                            resolver.update(PREFERAPN_URI, values2, null, null);
                            disabledWifi(connectivityManager);
                            enabledGprs(connectivityManager, telephonyManager);
                            if (cursor != null && !cursor.isClosed()) {
                                cursor.close();
                            }
                        } catch (Exception e) {
                            AndroidLogic.debug("处理网络连接时出错：" + e);
                            if (cursor != null && !cursor.isClosed()) {
                                cursor.close();
                            }
                            return false;
                        }
                    } catch (Throwable th) {
                        if (cursor != null && !cursor.isClosed()) {
                            cursor.close();
                        }
                        throw th;
                    }
                } else {
                    return false;
                }
            } else {
                AndroidLogic.debug("该系统暂不支持自动切换连接方式");
                disabledWifi(connectivityManager);
                enabledGprs(connectivityManager, (TelephonyManager) this.context.getSystemService("phone"));
            }
            for (int i = 0; i < 3; i++) {
                try {
                    Thread.sleep(3000L);
                    NetworkInfo networkInfo2 = connectivityManager.getActiveNetworkInfo();
                    AndroidLogic.debug("判断连接类型：" + networkInfo2);
                    if (networkInfo2 != null && networkInfo2.isConnected() && "cmwap".equals(networkInfo2.getExtraInfo())) {
                        if (sleepTime > 0) {
                            try {
                                AndroidLogic.debug("sleep " + sleepTime + " ms");
                                Thread.sleep(sleepTime);
                            } catch (InterruptedException e2) {
                            }
                        }
                        AndroidLogic.debug("已成功切换成cmwap连接");
                        return true;
                    }
                } catch (InterruptedException e3) {
                    return false;
                }
            }
        }
        return false;
    }

