            return this.mPathSoundIDMap.get(path).intValue();
        }
        int soundId = createSoundIdFromAsset(path);
        if (soundId != -1) {
            this.mSoundIdStreamIdMap.put(Integer.valueOf(soundId), -1);
            this.mPathSoundIDMap.put(path, Integer.valueOf(soundId));
            return soundId;
        }
        return soundId;
    }

